import{_ as a,o as n,c as t,a3 as i}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"SC-41 — Queue duyệt KYC (Admin)","description":"","frontmatter":{"title":"SC-41 — Queue duyệt KYC (Admin)"},"headers":[],"relativePath":"wireframes/admin/sc-41-queue-duyet-kyc.md","filePath":"wireframes/admin/sc-41-queue-duyet-kyc.md","lastUpdated":null}'),e={name:"wireframes/admin/sc-41-queue-duyet-kyc.md"};function l(c,s,d,p,r,h){return n(),t("div",null,[...s[0]||(s[0]=[i('<h1 id="sc-41-—-queue-duyet-kyc" tabindex="-1">SC-41 — Queue duyệt KYC <a class="header-anchor" href="#sc-41-—-queue-duyet-kyc" aria-label="Permalink to &quot;SC-41 — Queue duyệt KYC&quot;">​</a></h1><p><span class="wf-badge info">ADMIN</span> <span class="wf-badge danger">SLA 48H</span> <span class="wf-badge info">Route: /admin/kyc</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-40..49 · docs/02 FR-KYC-04/05 · docs/03 UC-02 · docs/08 BR-KYC / BR-ADM · docs/06 endpoints 47/48</span></p><p><strong>Ai xem màn này</strong>: Quản trị viên (guard ADMIN 🛡) — người duyệt hồ sơ xác minh CCCD thủ công (v1 không có API 1411/dữ liệu dân cư). <strong>Mục đích</strong>: xử lý queue <code>PENDING</code> đúng SLA 48h với thao tác tối thiểu: bảng sort quá-hạn-trước → mở drawer đối chiếu → Approve/Reject (reject bắt buộc reason 10–500 ký tự, hiện nguyên văn cho user). Mỗi quyết định = toast + audit log. <strong>Ví dụ số dùng trong bản vẽ</strong>: &quot;bây giờ&quot; 10/10/2026 14:31 (GMT+7) · queue 5 hồ sơ PENDING · 1 quá hạn (<code>LE VAN CUONG</code>, nộp 08/10/2026 08:12, deadline 48h = 10/10 08:12 → quá 6h) · hồ sơ mở drawer: <code>ky_01J9X2K8M2</code> của LE VAN CUONG, CCCD <code>031088456721</code>, DOB 21/03/1988 (38 tuổi).</p><h2 id="_1-desktop-—-queue-server-side-filter-sort-page-sla-badge" tabindex="-1">1. Desktop — queue server-side (filter/sort/page) + SLA badge <a class="header-anchor" href="#_1-desktop-—-queue-server-side-filter-sort-page-sla-badge" aria-label="Permalink to &quot;1. Desktop — queue server-side (filter/sort/page) + SLA badge&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/admin/kyc?status=PENDING&amp;page=1</span></div><div class="wf-body"><div class="wf-row" style="gap:0;align-items:stretch;"><div class="wf-admin-rail" style="border-radius:0;"><span class="brand">AnPhuc Admin</span><span class="item">Dashboard</span><span class="item active">KYC</span><span class="item">Tin</span><span class="item">Dự án</span><span class="item">Đấu giá</span><span class="item">Thanh toán</span><span class="item">Người dùng</span><span class="item">Audit</span><span class="item" style="margin-top:auto;color:#9ca3af;">← Về trang người dùng</span></div><div class="wf-grow wf-col" style="padding:16px;gap:12px;"><div class="wf-row between middle"><div class="wf-col" style="gap:2px;"><span class="wf-title xl">Queue duyệt KYC</span><span class="wf-small">SLA 48h giờ làm việc (BR-ADM-03) · sort: quá hạn trước, rồi submittedAt asc (FR-KYC-05) <span class="wf-callout">1</span></span></div><div class="wf-row middle" style="gap:8px;"><span class="wf-btn sm ghost">⭳ Export CSV</span><span class="wf-avatar">M</span></div></div><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);margin:0;"><b>1 hồ sơ quá hạn SLA 48h</b> — đã tự đẩy lên đầu bảng (nền đỏ). Alert này đồng bộ số liệu với Dashboard SC-40. <span class="wf-callout danger">2</span></div><div class="wf-row between middle" style="gap:8px;"><div class="wf-tabs" style="border-bottom:none;"><span class="wf-tab active">PENDING (5)</span><span class="wf-tab">APPROVED</span><span class="wf-tab">REJECTED</span><span class="wf-tab">Tất cả</span></div><div class="wf-search" style="max-width:300px;"><span>🔎</span><span>Tìm tên / email / số CCCD…</span></div></div><table class="wf-table"><thead><tr><th>Hồ sơ · Nộp lúc</th><th>Người nộp</th><th>CCCD</th><th>Tuổi</th><th>SLA 48h <span class="wf-callout">2</span></th><th>Lần nộp/30d</th><th></th></tr></thead><tbody><tr style="background:var(--wf-danger-soft);"><td><b>ky_01J9X2K8M2</b><br><span class="wf-small">08/10/2026 08:12</span></td><td><b>LE VAN CUONG</b><br><span class="wf-small">cuonglv@example.com · 0903 111 222</span></td><td>031088456721</td><td>38</td><td><span class="wf-sla over">quá 6h</span></td><td>1/3</td><td><span class="wf-btn sm primary">Xem ▸</span></td></tr><tr><td><b>ky_01J9Y5T3P8</b><br><span class="wf-small">08/10/2026 18:40</span></td><td><b>TRAN VAN HIEU</b><br><span class="wf-small">hieutv@example.com</span></td><td>031093557812</td><td>33</td><td><span class="wf-sla soon">còn 4h</span></td><td>2/3 <span class="wf-callout">6</span></td><td><span class="wf-btn sm">Xem ▸</span></td></tr><tr><td><b>ky_01J9Z1M4Q7</b><br><span class="wf-small">09/10/2026 20:15</span></td><td><b>TRAN THI BICH</b><br><span class="wf-small">bichtt@example.com</span></td><td>031095334874</td><td>31</td><td><span class="wf-sla ok">còn 30h</span></td><td>1/3</td><td><span class="wf-btn sm">Xem ▸</span></td></tr><tr><td><b>ky_01J9Z8R2W6</b><br><span class="wf-small">10/10/2026 09:00</span></td><td><b>PHAM VAN DUC</b><br><span class="wf-small">ducpv@example.com</span></td><td>031001228845</td><td>25</td><td><span class="wf-sla ok">còn 43h</span></td><td>1/3</td><td><span class="wf-btn sm">Xem ▸</span></td></tr><tr><td><b>ky_01J9ZC4X91</b><br><span class="wf-small">10/10/2026 13:30</span></td><td><b>VO THI MAI</b><br><span class="wf-small">maivt@example.com</span></td><td>031092774563</td><td>34</td><td><span class="wf-sla ok">còn 47h</span></td><td><b class="wf-warn-text">3/3 — lần cuối</b> <span class="wf-callout warn">6</span></td><td><span class="wf-btn sm">Xem ▸</span></td></tr></tbody></table><div class="wf-row between middle"><span class="wf-small">20 dòng/trang · tổng 5 hồ sơ PENDING · server-side (FE không sort/lọc trong bộ nhớ) <span class="wf-callout">1</span></span><div class="wf-pagination" style="margin-top:0;"><span class="pg">‹</span><span class="pg active">1</span><span class="pg">›</span></div></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/03 UC-02 · docs/02 FR-KYC-04/05 · docs/08 BR-KYC/BR-ADM)</div><ol><li><span class="num">1</span><span><b>DataTable server-side</b> `GET /admin/kyc-queue?status=&amp;page=` (endpoint 47): filter tab = query `status` (PENDING/APPROVED/REJECTED), phân trang offset 20/trang, URL sync (shareable giữa 2 admin). Sort mặc định: quá SLA trước → `submittedAt asc` (cũ nhất xử lý trước) — đúng FR-KYC-05. Search debounce 400ms. <span class="ref">FR-KYC-05</span> <span class="ref">docs/05 §3 SC-40..49</span></span></li><li><span class="num">2</span><span><b>SLA badge `wf-sla`</b> tính từ `slaReviewBy` (docs/06 §4.7 = submitted + 48h) so với GIỜ SERVER: `ok` (còn hạn) · `soon` (≤ 8h — vàng, sắp đến hạn) · `over` (đỏ nhấp nháy — quá hạn). Hàng quá hạn tint nền danger-soft; count &gt; 0 → banner đỏ đầu trang, đồng bộ Dashboard SC-40 (FR-STAT-01). <span class="ref">BR-ADM-03</span></span></li><li><span class="num">3</span><span><b>Tuổi hiển thị</b> = server đã check ≥18 lúc nộp (BR-KYC-01, `KYC_UNDERAGE` 422 chặn từ trước) — admin chỉ nhìn, không phải tự tính. CCCD hiển thị đủ 12 số cho admin (permission: ADMIN ✅ xem — docs/08 §9); với màn user khác vẫn mask. <span class="ref">BR-KYC-01</span> <span class="ref">NFR-S-05</span></span></li><li><span class="num">4</span><span><b>Click &quot;Xem ▸&quot; → mở drawer phải</b> (mục 2) — không điều hướng trang, giữ nguyên vị trí bảng + filter; ESC/click nền đóng drawer. Row vừa xử lý xong biến mất khỏi tab PENDING ngay (optimistic + refetch). <span class="ref">docs/05 §3</span></span></li><li><span class="num">5</span><span><b>Export CSV</b> theo filter hiện hành (`GET /admin/export/{entity}?filters`, max 50k dòng). Mọi mutation màn này (approve/reject) → <b>toast + audit log</b> (KYC_APPROVE/KYC_REJECT — actor, diff redact PII, ip, trace_id). <span class="ref">FR-STAT-02</span> <span class="ref">BR-ADM-01</span></span></li><li><span class="num">6</span><span><b>Lần nộp/30 ngày</b> (BR-KYC-06: tối đa 3 application/30 ngày rolling): cột này giúp admin biết reject lần này còn đường lui hay không — `3/3` hiện warn &quot;lần cuối&quot;: nếu reject, user hết quyền nộp lại trong 30 ngày (hướng dẫn liên hệ CS). Hover xem lịch sử application cũ trong drawer. <span class="ref">BR-KYC-06</span></span></li></ol></div><h2 id="_2-drawer-chi-tiet-ho-so-—-anh-cccd-signed-url-checklist-đoi-chieu" tabindex="-1">2. Drawer chi tiết hồ sơ — ảnh CCCD signed URL + checklist đối chiếu <a class="header-anchor" href="#_2-drawer-chi-tiet-ho-so-—-anh-cccd-signed-url-checklist-đoi-chieu" aria-label="Permalink to &quot;2. Drawer chi tiết hồ sơ — ảnh CCCD signed URL + checklist đối chiếu&quot;">​</a></h2><div class="wf"><div class="wf-row" style="justify-content:center;"><div class="wf-drawer" style="width:520px;max-width:100%;border-radius:12px;"><div class="wf-row between middle"><span class="wf-title lg">Hồ sơ ky_01J9X2K8M2 <span class="wf-badge warn">PENDING</span></span><span class="wf-btn sm ghost">✕ Đóng</span></div><div class="wf-row between middle" style="margin-top:6px;"><span class="wf-small">Nộp 08/10/2026 08:12 · deadline SLA 10/10/2026 08:12 (GMT+7)</span><span class="wf-sla over">QUÁ HẠN 6H</span></div><div class="wf-card flat" style="margin-top:10px;"><div class="pad wf-col" style="gap:6px;"><span class="wf-title">Người nộp</span><div class="wf-row between"><span class="wf-text">Họ tên khai báo</span><span class="wf-strong">LE VAN CUONG</span></div><div class="wf-row between"><span class="wf-text">Ngày sinh</span><span>21/03/1988 (38 tuổi)</span></div><div class="wf-row between"><span class="wf-text">CCCD</span><span class="wf-strong">031088456721</span></div><div class="wf-row between"><span class="wf-text">Email · SĐT</span><span>cuonglv@example.com · 0903 111 222</span></div><div class="wf-row between"><span class="wf-text">Tài khoản</span><span class="wf-row middle" style="gap:6px;"><span class="wf-badge ok">ACTIVE</span><span class="wf-small">thành viên từ 05/10/2026</span></span></div><div class="wf-row between"><span class="wf-text">Lần nộp trong 30 ngày</span><span>1/3 — chưa có lịch sử REJECTED</span></div></div></div><div class="wf-row middle" style="gap:8px;margin-top:10px;"><div class="wf-img" style="flex:1;min-height:130px;"><span>CCCD — MẶT TRƯỚC</span></div><div class="wf-img" style="flex:1;min-height:130px;"><span>CCCD — MẶT SAU</span></div></div><span class="wf-small">Ảnh tải qua `GET /media/{id}` — signed URL TTL ≤ 5 phút; click = lightbox phóng to (zoom/pinch) để soi chống làm giả. Hết TTL → nút &quot;Tải lại ảnh&quot;. <span class="wf-callout">7</span></span><div class="wf-card flat" style="margin-top:10px;"><div class="pad wf-col" style="gap:8px;"><span class="wf-title">Checklist đối chiếu <span class="wf-callout">8</span></span><span class="wf-checkbox checked">Họ tên khai báo trùng khít tên trên CCCD (đối chiếu trực quan — chuẩn không dấu/NFC)</span><span class="wf-checkbox checked">Ngày sinh khớp CCCD · ≥18 tuổi (server pre-check)</span><span class="wf-checkbox">Số CCCD trên ảnh đọc rõ, đủ 12 số, khớp số khai báo</span><span class="wf-checkbox checked">Ảnh rõ, không che góc, đúng 2 mặt (JPEG/PNG/WEBP ≤5MB — server pre-check)</span><span class="wf-checkbox checked">CCCD chưa từng APPROVED cho tài khoản khác (hash pre-check — hệ thống ✓)</span><span class="wf-small wf-warn-text">Nút DUYỆT chỉ enable khi admin tick đủ các ô đối chiếu trực quan — tick là tuyên bố chịu trách nhiệm, lưu vào audit diff.</span></div></div><div class="wf-row" style="margin-top:12px;"><span class="wf-btn ok" style="flex:1;">✓ DUYỆT (APPROVE)</span><span class="wf-btn danger" style="flex:1;">✕ TỪ CHỐI (REJECT)</span></div><span class="wf-small wf-center" style="margin-top:6px;">Quyết định là terminal cho hồ sơ này (PENDING → APPROVED/REJECTED — không hoàn tác); sai sót sau duyệt xử lý qua SC-48 (suspend) + user nộp hồ sơ mới.</span></div></div></div><div class="wf-legend"><div class="t">Chú thích drawer</div><ol><li><span class="num">7</span><span><b>Ảnh CCCD = dữ liệu nhạy cảm NĐ13</b>: chỉ ADMIN + owner đọc được, signed URL TTL ≤ 5 phút (endpoint 21, NFR-S-05); không cache browser, không nút tải về máy, watermark email admin đang xem (đề xuất design — chống chụp màn hình tuồn ra ngoài). FE tự refresh URL khi mở lại drawer. <span class="ref">FR-HS-08</span> <span class="ref">NFR-S-05</span></span></li><li><span class="num">8</span><span><b>Checklist = quy trình BR-KYC-02 (hard, quy trình duyệt)</b>: v1 duyệt thủ công 100% — admin đối chiếu trực quan tên/DOB/số. Các ô &quot;server pre-check&quot; (tuổi ≥18, format ảnh, hash CCCD unique) hệ thống đã chặn từ lúc nộp — hiện ✓ để admin khỏi làm lại; các ô trực quan admin PHẢI tick. Tick đủ → mới enable APPROVE. <span class="ref">BR-KYC-01/02/03</span> <span class="ref">BR-IDT-06</span></span></li><li><span class="num">9</span><span><b>Hai nút quyết định</b>: APPROVE xanh ok, REJECT đỏ danger — không có &quot;để lại sau&quot; (muộn là vi phạm SLA; cần thêm thông tin = REJECT kèm reason yêu cầu chụp lại, UC-02 AF-1). Đang gửi → cả hai nút loading disabled (chống double-submit). <span class="ref">UC-02 AF-1</span></span></li></ol></div><h2 id="_3-modal-xac-nhan-approve-reason-ghi-chu-bat-buoc-theo-quy-trinh-ops" tabindex="-1">3. Modal xác nhận APPROVE (reason ghi chú bắt buộc theo quy trình Ops) <a class="header-anchor" href="#_3-modal-xac-nhan-approve-reason-ghi-chu-bat-buoc-theo-quy-trinh-ops" aria-label="Permalink to &quot;3. Modal xác nhận APPROVE (reason ghi chú bắt buộc theo quy trình Ops)&quot;">​</a></h2><div class="wf"><div class="wf-modal-overlay"><div class="wf-modal"><div class="head">Xác nhận duyệt hồ sơ KYC</div><div class="wf-lines" style="margin:10px 0;"><div class="wf-row between"><span class="wf-text">Hồ sơ</span><span class="wf-strong">ky_01J9X2K8M2 — LE VAN CUONG</span></div><div class="wf-row between"><span class="wf-text">CCCD</span><span class="wf-strong">031088456721</span></div><div class="wf-row between"><span class="wf-text">SLA</span><span class="wf-sla over">quá 6h — duyệt ngay</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Ghi chú duyệt (bắt buộc — quy trình Ops, lưu audit) <span class="wf-callout">10</span></span><div class="wf-input filled"><span>Đã đối chiếu ảnh 2 mặt — tên/DOB/số khớp khai báo</span><span class="caret">✎</span></div></div><div class="wf-note">Sau duyệt: user mở khóa đăng tin · đăng ký đấu giá · đặt lịch xem (KYC APPROVED là điều kiện tiên quyết); NTF KYC_DECISION gửi in-app + email. Audit `KYC_APPROVE` ghi actor + reviewedAt — không thể hoàn tác.</div><div class="wf-row" style="margin-top:12px;"><span class="wf-btn" style="flex:1;">Hủy</span><span class="wf-btn ok" style="flex:1;">XÁC NHẬN DUYỆT</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">10</span><span><b>API nhận `reason?` optional khi APPROVE</b> (docs/06 endpoint 48) — nhưng quy trình Ops trên wireframe này BẮT BUỘC ghi chú ngắn để audit có ngữ cảnh (FE enforce, BE vẫn optional; không đổi contract). `PATCH /admin/kyc/{id}` body `{decision: &quot;APPROVE&quot;, reason}` → ghi `reviewedBy/reviewedAt` (FR-KYC-04) → `KycApprovedEvent` → NTF-02. <span class="ref">FR-KYC-04</span> <span class="ref">BR-KYC-08</span> <span class="ref">BR-ADM-01</span></span></li></ol></div><h2 id="_4-modal-reject-—-reason-bat-buoc-10–500-ky-tu-hien-nguyen-van-cho-user" tabindex="-1">4. Modal REJECT — reason bắt buộc 10–500 ký tự, hiện NGUYÊN VĂN cho user <a class="header-anchor" href="#_4-modal-reject-—-reason-bat-buoc-10–500-ky-tu-hien-nguyen-van-cho-user" aria-label="Permalink to &quot;4. Modal REJECT — reason bắt buộc 10–500 ký tự, hiện NGUYÊN VĂN cho user&quot;">​</a></h2><div class="wf"><div class="wf-modal-overlay"><div class="wf-modal"><div class="head" style="color:var(--wf-danger);">Từ chối hồ sơ KYC — LE VAN CUONG</div><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);"><b>Lý do sẽ hiển thị NGUYÊN VĂN cho user</b> (banner REJECTED ở SC-21 + NTF + email) — viết tiếng Việt rõ ràng, nêu đúng lỗi và cách khắc phục. Không thông tin nội bộ, không tên admin. <span class="wf-callout danger">11</span></div><div class="wf-col" style="gap:4px;margin-top:8px;"><span class="wf-small wf-strong">Lý do từ chối * (10–500 ký tự)</span><div class="wf-input error" style="min-height:76px;align-items:flex-start;"><span class="wf-small">Ảnh mặt sau bị mờ</span><span class="caret">✎</span></div><div class="wf-row between"><span class="wf-field-error">Lý do tối thiểu 10 ký tự — hãy nêu cách khắc phục (VD: &quot;Ảnh mặt sau bị mờ góc phải — chụp lại đủ 4 góc, không lóa sáng&quot;)</span><span class="wf-small">18/500</span></div></div><div class="wf-col" style="gap:4px;margin-top:6px;"><span class="wf-small">Mẫu nhanh (chèn vào ô, admin vẫn phải rà lại):</span><div class="wf-row wrap" style="gap:6px;"><span class="wf-btn sm ghost">Ảnh mờ / che góc — chụp lại</span><span class="wf-btn sm ghost">Họ tên khai báo không khớp CCCD</span><span class="wf-btn sm ghost">CCCD hết hạn / không đủ 12 số</span></div></div><div class="wf-note">User được nộp lại hồ sơ mới sau reject — nhưng đếm vào giới hạn <b>3 lần/30 ngày</b> (hồ sơ này là lần 1/3). Vượt → `KYC_ATTEMPT_LIMIT`, user phải liên hệ CS 1900-xxx.</div><div class="wf-row" style="margin-top:12px;"><span class="wf-btn" style="flex:1;">Hủy</span><span class="wf-btn danger disabled" style="flex:1;">XÁC NHẬN TỪ CHỐI</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">11</span><span><b>Reason reject = hard rule BR-KYC-04</b>: 10–500 ký tự, hiển thị nguyên văn cho user. FE: counter realtime, nút disabled + field error khi &lt;10 ký tự; server re-check (400 `VALIDATION_ERROR` → map field). NTF KYC_DECISION (in-app + email) chứa đúng reason này (SC-28 callout 5). Audit `KYC_REJECT` lưu reason trong diff. <span class="ref">BR-KYC-04</span> <span class="ref">FR-KYC-04</span> <span class="ref">BR-ADM-01</span></span></li><li><span class="num">12</span><span><b>Chips &quot;mẫu nhanh&quot; chỉ là tiện ích FE</b> (không phải enum server) — chèn text vào ô, admin sửa được; không giới hạn reason vào mẫu. <span class="ref">UC-02 AF-1</span></span></li></ol></div><h2 id="_5-toast-ket-qua-race-2-admin-409-invalid-transition" tabindex="-1">5. Toast kết quả &amp; race 2 admin (409 INVALID_TRANSITION) <a class="header-anchor" href="#_5-toast-ket-qua-race-2-admin-409-invalid-transition" aria-label="Permalink to &quot;5. Toast kết quả &amp; race 2 admin (409 INVALID_TRANSITION)&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:640px;gap:4px;"><span class="wf-state-label">APPROVE THÀNH CÔNG (200)</span><div class="wf-toast ok"><b>Đã duyệt hồ sơ ky_01J9X2K8M2</b> — LE VAN CUONG đã nhận thông báo KYC_DECISION (in-app + email)</div><span class="wf-state-label" style="margin-top:10px;">REJECT THÀNH CÔNG (200)</span><div class="wf-toast warn"><b>Đã từ chối hồ sơ ky_01J9X2K8M2</b> — lý do đã gửi nguyên văn tới user; user còn 2 lần nộp lại trong 30 ngày</div><span class="wf-state-label" style="margin-top:10px;">409 — HỒ SƠ VỪA ĐƯỢC ADMIN KHÁC XỬ LÝ (UC-02 EF-4)</span><div class="wf-toast info">Hồ sơ vừa được xử lý bởi <b>admin.lan</b> lúc 14:30 — danh sách đã được làm mới</div><span class="wf-small">Xảy ra khi 2 admin cùng mở 1 hồ sơ: người bấm sau nhận 409 `INVALID_TRANSITION` → FE đóng drawer + refetch queue + toast info nêu TÊN người đã xử lý (minh bạch nội bộ, không đổ lỗi). Không mất dữ liệu, không retry tự động. <span class="wf-callout">13</span></span><span class="wf-state-label" style="margin-top:10px;">SIGNED URL HẾT HẠN (TTL 5 phút)</span><div class="wf-toast info">Link ảnh CCCD hết hạn — đang tải lại ảnh mới…</div><span class="wf-small">Tự gọi lại `GET /media/{id}` lấy signed URL mới, không bắt admin reload trang.</span></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">13</span><span><b>Mọi quyết định → toast + audit log</b> (pattern chuẩn admin docs/05 §3). Toast success tự ẩn 5s; toast 409 kèm hành động &quot;Hoàn tác?&quot; — KHÔNG, quyết định terminal (docs/08 §10.6), chỉ refresh. Copy toast là bản duy nhất, đặt trong constants (NFR-C-01). <span class="ref">BR-ADM-01/02</span></span></li></ol></div><h2 id="_6-bon-trang-thai-man-loading-empty-error-data-over-sla-highlight" tabindex="-1">6. Bốn trạng thái màn (Loading / Empty / Error / Data) + over-SLA highlight <a class="header-anchor" href="#_6-bon-trang-thai-man-loading-empty-error-data-over-sla-highlight" aria-label="Permalink to &quot;6. Bốn trạng thái màn (Loading / Empty / Error / Data) + over-SLA highlight&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-2"><div class="wf-col"><span class="wf-state-label">LOADING — SKELETON TABLE</span><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><div class="wf-skeleton" style="height:32px;"></div><div class="wf-skeleton" style="height:44px;"></div><div class="wf-skeleton" style="height:44px;"></div><div class="wf-skeleton" style="height:44px;"></div><div class="wf-skeleton" style="height:44px;"></div><div class="wf-skeleton" style="height:44px;"></div><span class="wf-small">Header + tabs + nút export hiện ngay (không skeleton) — chỉ thân bảng nhấp nháy; giữ filter cũ khi đổi tab (không flash empty).</span></div></div></div><div class="wf-col"><span class="wf-state-label">EMPTY — QUEUE TRỐNG</span><div class="wf-card"><div class="pad"><div class="wf-empty"><span class="icon">✓</span><div class="wf-title">Queue trống — không còn hồ sơ KYC chờ duyệt</div><div class="wf-text" style="margin-top:6px;">Toàn bộ hồ sơ đã xử lý trong SLA 48h. Trang tự kiểm tra hồ sơ mới mỗi 60 giây.</div><span class="wf-btn ghost" style="margin-top:12px;">Xem tab APPROVED gần đây →</span></div><span class="wf-small">Empty của tab REJECTED/APPROVED (do filter) → copy khác: &quot;Không có hồ sơ khớp bộ lọc&quot; + nút &quot;Xóa filter&quot;. Icon ✓ là placeholder — production dùng icon set thật.</span></div></div></div><div class="wf-col"><span class="wf-state-label">ERROR — KHÔNG LOAD ĐƯỢC QUEUE</span><div class="wf-card"><div class="pad"><div class="wf-error-box"><div class="wf-title">Không tải được queue KYC</div><div class="wf-text" style="margin-top:6px;">Thử lại; nếu tiếp diễn báo Tech Lead kèm mã trace (SLA vẫn chạy — không vì lỗi UI mà hồ sơ quá hạn âm thầm).</div><div class="wf-trace" style="margin-top:8px;">traceId: 3ee1b90c…4a7d</div><span class="wf-btn" style="margin-top:10px;">Thử lại</span></div></div></div></div><div class="wf-col"><span class="wf-state-label">OVER-SLA — ZOOM 1 DÒNG QUÁ HẠN</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><table class="wf-table"><tbody><tr style="background:var(--wf-danger-soft);"><td><b>ky_01J9X2K8M2</b><br><span class="wf-small">08/10/2026 08:12</span></td><td><b>LE VAN CUONG</b></td><td><span class="wf-sla over">quá 6h</span></td></tr></tbody></table><span class="wf-small">3 lớp tín hiệu chồng nhau cho quá hạn (không chỉ dựa màu — accessibility): badge đỏ NHẤP NHÁY `wf-sla over` + tint nền dòng + banner đếm đầu trang + vị trí đầu bảng. Alert Grafana phía BE (SLA &gt; 72h — NFR-O-01) là kênh song song, UI không thay thế. <span class="ref">BR-ADM-03</span> <span class="ref">docs/05 §1.7</span></span></div></div></div></div></div><h2 id="_7-responsive-—-desktop-priority" tabindex="-1">7. Responsive — desktop-priority <a class="header-anchor" href="#_7-responsive-—-desktop-priority" aria-label="Permalink to &quot;7. Responsive — desktop-priority&quot;">​</a></h2><div class="wf"><div class="wf-card" style="max-width:720px;"><div class="pad"><span class="wf-title">Ghi chú responsive (không vẽ frame mobile đầy đủ)</span><div class="wf-text" style="margin-top:6px;">Màn duyệt KYC là desktop-priority (docs/05 §1.2): drawer cần không gian đặt 2 ảnh CCCD cạnh checklist. Dưới 1024px: rail collapse hamburger; bảng scroll ngang (sticky cột &quot;Hồ sơ&quot; + cột action); drawer chiếm full-width từ phải. Dưới 768px ảnh CCCD xếp dọc, checklist ngay dưới ảnh, 2 nút quyết định sticky đáy. Mobile chỉ khuyến cáo cho thao tác KHẨN (hồ sơ quá hạn) — không phải ca làm việc chính.</div></div></div></div><h2 id="_8-checklist-designer-khi-dung-figma-cho-sc-41" tabindex="-1">8. Checklist designer khi dựng Figma cho SC-41 <a class="header-anchor" href="#_8-checklist-designer-khi-dung-figma-cho-sc-41" aria-label="Permalink to &quot;8. Checklist designer khi dựng Figma cho SC-41&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (rail + bảng + drawer 520px) / tablet (drawer full-width, bảng scroll ngang) / mobile khẩn cấp</li><li>[ ] Đủ trạng thái: skeleton · empty (queue trống + empty do filter) · error + traceId · data · over-SLA highlight (badge nhấp nháy + tint dòng + banner + đầu bảng)</li><li>[ ] Drawer: 2 ảnh CCCD lightbox + note signed URL TTL 5&#39; + watermark đề xuất; checklist tách rõ ô &quot;server pre-check ✓&quot; vs ô admin tự tick; DUYỆT chỉ enable khi tick đủ</li><li>[ ] Modal approve (ghi chú Ops) + modal reject (counter 10–500, field error, chips mẫu nhanh, nút disabled tới khi hợp lệ)</li><li>[ ] Toast đủ 4 biến thể: approve ok · reject warn · 409 info (tên người xử lý trước) · signed-URL hết hạn</li><li>[ ] Cột &quot;Lần nộp/30d&quot; có trạng thái warn 3/3 &quot;lần cuối&quot; (BR-KYC-06)</li><li>[ ] Không emoji icon production (✓/✕/🔎/⭳ là placeholder); copy lỗi nguyên văn docs/06 §5; giờ <code>dd/MM/yyyy HH:mm</code> + GMT+7</li><li>[ ] Note FE: URL sync filter/page · debounce search 400ms · refetch sau mutation · chống double-submit (nút loading) · mọi mutation audit (BR-ADM-01)</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ cần PM duyệt trên docs/08 trước.</p></div>',25)])])}const u=a(e,[["render",l]]);export{g as __pageData,u as default};
